"""Original adrenal chapter: cortisol excess and incidentaloma decision pathways."""
from create_adrenal import rows,q,AI,GC,EC
from qbank_authoring import ref
CU=ref('Pituitary Society: Cushing Disease Diagnosis and Management Update, 2021','https://pmc.ncbi.nlm.nih.gov/articles/PMC8743006/')
IN=ref('ESE/ENSAT Adrenal Incidentaloma Guideline, 2023','https://doi.org/10.1093/ejendo/lvad066')
CAH=ref('Endocrine Society: Steroid 21-Hydroxylase Deficiency Guideline, 2018','https://pmc.ncbi.nlm.nih.gov/articles/PMC6456929/')
for item in rows:
 if '17-hydroxyprogesterone' in item['question'] or 'Congenital adrenal hyperplasia' in item['question']:item['references'].append(CAH)
q('Cushingoid features are recognized in an adult. What exposure should be assessed before testing for endogenous cortisol excess?', 'Glucocorticoids from all routes, including injections, inhalers, creams and supplements',[
 ('Only prescribed oral tablets can cause exogenous Cushing syndrome','Other routes and hidden ingredients can produce systemic exposure.'),('A low morning cortisol excludes exogenous steroid excess','Exogenous exposure can suppress endogenous cortisol.'),('Imaging should always precede medication history','Incidental lesions can mislead before the biochemical mechanism is established.')],
 'The commonest mechanism may be iatrogenic', '**Exogenous glucocorticoids can produce clinical excess while suppressing measured endogenous cortisol.**',['Potency, duration and metabolism interactions affect exposure.','Unregulated products may contain steroid ingredients.'], '**Do not stop a long exposure abruptly without considering adrenal reserve.**',['Review the underlying treatment need.','Use an appropriate withdrawal and stress-coverage plan.'],[['Exposure review','All routes and products'],['Endogenous cortisol','Can be suppressed'],['Withdrawal','Potential adrenal-insufficiency risk']],[GC,CU])
q('Which clinical cluster is more discriminatory for endogenous Cushing syndrome than isolated obesity?', 'Proximal muscle weakness, easy bruising and broad violaceous striae',[
 ('Obesity and fatigue alone','These are common nonspecific features.'),('Mild hypertension alone','It is prevalent without Cushing syndrome.'),('One elevated random cortisol during acute stress','Stress can raise cortisol without autonomous disease.')],
 'Use progressive discriminatory signs to select testing', '**Catabolic skin and muscle findings increase suspicion.**',['Unusual osteoporosis or early severe comorbidity can also prompt assessment.','The phenotype varies with duration and severity.'], '**Choose validated screening rather than a random cortisol.**',['Exclude exogenous exposure.','Interpret results in the presence of depression, alcohol use or severe illness that can alter the axis.'],[['More specific','Bruising, weakness and purple striae'],['Less specific alone','Obesity, fatigue and hypertension'],['Testing','Validated hypercortisolism pathway']],[CU],'clinical_scenario')
q('Which is an appropriate initial test for suspected endogenous hypercortisolism in a suitable patient?', 'One-milligram overnight dexamethasone suppression, late-night salivary cortisol or repeated 24-hour urinary free cortisol according to context',[
 ('A single random serum cortisol as the universal screening test','Random cortisol is not a recommended screening strategy.'),('Pituitary MRI alone','An image cannot establish cortisol excess.'),('ACTH alone before confirming hypercortisolism','ACTH is used for source branching after the syndrome is established.')],
 'The tests assess different disrupted physiological properties', '**Dexamethasone tests feedback, late-night saliva tests circadian nadir and urine estimates integrated free cortisol.**',['Repetition is often required.','Shift work, renal impairment and drugs affect test selection.'], '**Confirm abnormal findings before localization.**',['Choose a second appropriate test when needed.','Avoid imaging an unconfirmed syndrome into existence.'],[['DST','Feedback suppression'],['Late-night saliva','Circadian nadir'],['Urinary free cortisol','Integrated free cortisol']],[CU])
q('A woman on oral estrogen has an abnormal dexamethasone suppression result but limited clinical suspicion. What confounder should be considered?', 'Increased cortisol-binding globulin can raise measured total serum cortisol',[
 ('Oral estrogen necessarily causes an ACTH-secreting tumor','It changes binding proteins rather than proving a tumor.'),('All cortisol assays measure only unbound hormone','Routine serum cortisol is largely a total measurement.'),('The result alone requires adrenalectomy','Analytical and physiological confounders require clarification.')],
 'A feedback test can be affected by the measured hormone fraction', '**Oral estrogen can increase CBG and apparent total cortisol.**',['Drugs that alter dexamethasone metabolism can also distort the test.','Adherence and dexamethasone exposure matter.'], '**Choose repeat or alternative testing safely.**',['Consider an appropriate free-cortisol-based method or managed medication adjustment.','Do not interrupt necessary therapy without a plan.'],[['Confounder','High CBG'],['Measured result','Higher total cortisol'],['Response','Context-appropriate confirmation']],[CU],'clinical_scenario')
q('Symptoms strongly suggest episodic cortisol excess but initial screening is normal during a well interval. What approach is appropriate?', 'Repeat suitable testing during symptomatic phases and consider cyclic hypercortisolism',[
 ('One normal sample excludes every cyclic syndrome','Intermittent secretion can be missed.'),('Proceed directly to pituitary surgery without confirmation','Biochemical evidence remains necessary.'),('Use IPSS to prove hypercortisolism in a normal phase','IPSS is not an initial diagnostic test for the syndrome.')],
 'Timing can determine diagnostic sensitivity', '**Serial late-night saliva or urinary collections may capture episodes.**',['The exact choice depends on the patient and test limitations.','False-positive pseudo-Cushing states remain part of the differential.'], '**Use specialist longitudinal assessment.**',['Document symptom timing and results.','Avoid repeated invasive localization before establishing active biochemical disease.'],[['Pattern','Intermittent symptoms'],['Problem','Normal testing between episodes'],['Plan','Serial phase-appropriate testing']],[CU],'clinical_scenario')
q('Endogenous hypercortisolism is confirmed and ACTH is suppressed. Which source pathway is most appropriate?', 'Evaluate an ACTH-independent adrenal mechanism',[
 ('Diagnose pituitary Cushing disease solely from a small pituitary incidentaloma','The dependency pattern points away from pituitary ACTH drive.'),('Perform IPSS in every low-ACTH case','It is not the appropriate first localization branch.'),('ACTH suppression means cortisol cannot be elevated','Autonomous adrenal cortisol suppresses ACTH.')],
 'Dependency directs localization', '**An adrenal adenoma, carcinoma or bilateral adrenal process can produce autonomous cortisol.**',['Imaging and steroid patterns refine the cause.','Assay and medication issues should be considered when the pattern is inconsistent.'], '**Assess severity and comorbidity while localizing.**',['Severe cortisol excess can create infection, thrombosis and electrolyte risk.','Definitive treatment depends on the established source.'],[['ACTH suppressed','Adrenal/independent pathway'],['ACTH nonsuppressed','Dependent pathway'],['Imaging','Mechanism directed']],[CU,IN])
q('Which mechanism lowers cortisol with metyrapone?', 'Inhibition of adrenal 11-beta-hydroxylase',[
 ('Direct blockade of the glucocorticoid receptor','That describes mifepristone.'),('Dopamine D2 agonism','That describes cabergoline.'),('Destruction of all pituitary ACTH cells by an antibody','That is not metyrapone’s action.')],
 'Steroidogenesis inhibition changes precursor concentrations', '**Metyrapone reduces conversion of 11-deoxycortisol to cortisol.**',['Mineralocorticoid- and androgen-related precursors can rise.','Assay cross-reactivity can complicate cortisol interpretation.'], '**Monitor for both ongoing excess and adrenal insufficiency.**',['Potassium, blood pressure and symptoms matter.','Use an expert biochemical and clinical monitoring plan.'],[['Target','11-beta-hydroxylase'],['Effect','Less cortisol synthesis'],['Monitoring','Cortisol context, potassium and clinical state']],[CU])
q('Why cannot serum cortisol normalization be used as the efficacy target during mifepristone treatment of Cushing syndrome?', 'It blocks glucocorticoid receptor action rather than reliably lowering cortisol production',[
 ('Mifepristone is a direct cortisol synthesis inhibitor','Its principal relevant effect is receptor antagonism.'),('Cortisol must become undetectable for benefit','It can remain high or rise despite clinical receptor blockade.'),('No adverse-effect monitoring is necessary','Potassium and clinical features require close follow-up.')],
 'The treatment mechanism changes how response is judged', '**Clinical and metabolic effects guide assessment.**',['Signs of excessive blockade can resemble adrenal insufficiency despite high cortisol.','Hypokalemia and progesterone-receptor-related effects are relevant.'], '**Use a specialist safety plan.**',['Do not escalate solely because cortisol remains elevated.','Review pregnancy contraindications and drug interactions.'],[['Action','Glucocorticoid receptor antagonism'],['Cortisol level','Not an efficacy normalization target'],['Monitoring','Clinical/metabolic and potassium']],[CU])
q('A homogeneous adrenal incidentaloma measures 7 HU on noncontrast CT with no other suspicious imaging feature. What is the 2023 ESE imaging principle?', 'No further imaging is generally required for this benign phenotype, independent of size',[
 ('Every lesion requires annual imaging forever','The 2023 guideline de-escalates clear lipid-rich benign lesions.'),('A benign CT phenotype removes every need for clinical hormonal assessment','Imaging and hormone evaluation are separate questions.'),('Biopsy is mandatory for all low-HU masses','This is unnecessary and potentially harmful.')],
 'Low unenhanced attenuation can establish a benign imaging phenotype', '**Homogeneous lesions at most 10 HU are considered benign in this guideline context.**',['The rule requires a technically appropriate noncontrast assessment.','A heterogeneous or indeterminate lesion follows a different pathway.'], '**Complete the indicated clinical endocrine assessment.**',['Do not transfer the rule to a suspicious cancer context without review.','Avoid unnecessary serial scans once benignity is established.'],[['Appearance','Homogeneous'],['Noncontrast HU','At most 10'],['Imaging follow-up','Usually none required']],[IN],'clinical_scenario')
q('An adrenal incidentaloma is associated with cortisol 3.2 µg/dL after 1-mg dexamethasone, without overt Cushing features. What does the 2023 ESE framework call this after confirming the context?', 'Mild autonomous cortisol secretion',[
 ('Overt Cushing syndrome is proven solely by this value','The absence of overt clinical features and integrated assessment matter.'),('Normal suppression because the value is below 5','The updated MACS threshold is above 1.8 µg/dL, not only above 5.'),('A pheochromocytoma diagnosis','This is a cortisol-feedback test.')],
 'MACS recognizes lower-grade autonomous exposure', '**Post-DST cortisol above 1.8 µg/dL is the framework threshold when overt Cushing syndrome is absent.**',['Confirm ACTH independence and consider test confounders.','Hypertension, diabetes and skeletal effects inform clinical significance.'], '**Individualize surgery versus observation.**',['A numerical result alone does not mandate adrenalectomy.','Age, comorbidities, degree of autonomy and preferences matter.'],[['Threshold','Post-DST above 1.8 µg/dL'],['Clinical phenotype','No overt Cushing syndrome'],['Decision','Comorbidity- and patient-based']],[IN],'clinical_scenario')
q('Which nuance applies to pheochromocytoma biochemical testing in the 2023 ESE incidentaloma guideline?', 'Routine metanephrines may be omitted for a clearly homogeneous lipid-rich lesion at most 10 HU, while atypical lesions require testing',[
 ('Every indeterminate lesion can skip testing because the patient has no symptoms','Pheochromocytoma can be asymptomatic.'),('A low-HU rule applies to every scan regardless of technique or heterogeneity','The benign imaging criteria must actually be met.'),('No adrenal lesion ever needs hormonal assessment','Function can change management and procedural safety.')],
 'The updated guideline uses imaging probability to tailor testing', '**Metanephrines are recommended when imaging is not typical of a benign adenoma.**',['A clinically suspicious catecholamine syndrome still warrants assessment.','No unenhanced CT or uncertain characterization limits use of the exception.'], '**Do not use the exception before an unsafe biopsy of an indeterminate mass.**',['Review the complete history and imaging.','Use plasma or urinary testing according to the appropriate protocol when indicated.'],[['Typical benign adenoma','Possible metanephrine exception'],['Indeterminate/atypical','Test'],['Clinical suspicion','Evaluate regardless of shortcut']],[IN])
q('An indeterminate adrenal mass is found in a patient with another malignancy. Before considering biopsy, which condition is essential?', 'Exclude pheochromocytoma and establish that histology would change management',[
 ('Biopsy every adrenal mass before checking hormones','This can precipitate a catecholamine crisis.'),('Biopsy is the routine way to distinguish every adrenal cortical adenoma from carcinoma','It is not the standard strategy for a suspected primary adrenocortical carcinoma.'),('A history of cancer makes all adrenal masses proven metastases','Benign lesions and pheochromocytoma remain possible.')],
 'Adrenal biopsy has a restricted role', '**The 2023 guideline requires hormonal inactivity, indeterminate imaging and a management-changing result.**',['Pheochromocytoma exclusion is particularly important.','Primary adrenal cancer can require an oncological surgical pathway rather than needle diagnosis.'], '**Use multidisciplinary review.**',['Assess whether imaging or another safer target can answer the question.','Do not perform a procedure simply because a mass exists.'],[['Safety','Exclude catecholamine tumor'],['Diagnostic need','Not conclusively benign'],['Utility','Result changes management']],[IN],'clinical_scenario')
